INSERT INTO `v1_900885b0bfc09c39a2b99ea981c7f02b5934db6f5f3d8dbff9b9d396cf4d00b5` VALUES ("", 0, 0, 20172, 1201720009, 21, "vo_travel_talk", "", "", "", "vo_travel_talk_20017_01");
INSERT INTO `v1_900885b0bfc09c39a2b99ea981c7f02b5934db6f5f3d8dbff9b9d396cf4d00b5` VALUES (0, 1, 10, 20172, 1201720010, 11, 106611, 1, 0, 0, "あ、相変わらずのケンカバカですね……\nあたしはこんな面倒な仕事放り出して、\nさっさとランドソルに帰りてーですよ。");
INSERT INTO `v1_900885b0bfc09c39a2b99ea981c7f02b5934db6f5f3d8dbff9b9d396cf4d00b5` VALUES ("", "", "", 20172, 1201720011, 91, 0, "", "", "", "");
